package com.ecommerce.service;
import com.ecommerce.dto.AdminDtos.InventoryAdjustmentRequest; import com.ecommerce.dto.CatalogDtos.ProductResponse; import com.ecommerce.exception.ApiException; import com.ecommerce.model.*; import com.ecommerce.repository.*; import org.springframework.cache.annotation.CacheEvict; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class InventoryService { private final ProductRepository products; private final InventoryTransactionRepository txs; private final CatalogService catalog; public InventoryService(ProductRepository products,InventoryTransactionRepository txs,CatalogService catalog){this.products=products;this.txs=txs;this.catalog=catalog;} @Transactional @CacheEvict(value="products",allEntries=true) public ProductResponse adjust(Long productId,InventoryAdjustmentRequest r){ Product p=products.findById(productId).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Product not found")); int updated=p.getStockQuantity()+r.quantityChange(); if(updated<0) throw new ApiException(HttpStatus.BAD_REQUEST,"Inventory cannot become negative"); p.setStockQuantity(updated); InventoryTransaction tx=new InventoryTransaction(); tx.setProduct(p); tx.setQuantityChange(r.quantityChange()); tx.setReason(r.reason()); txs.save(tx); return catalog.toProductResponse(p); } }